from itertools import combinations


def _route(policy, data):
    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    source = data["source"]
    initial_mask = bit.get(source, 0)
    budget = data["coupons"]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    start = data["start"]
    initial = (source, initial_mask, 0)
    best = {initial: start}
    queue = [(start, source, initial_mask, 0)]
    deadline = data["deadline"]

    while queue:
        arrival, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if best.get(state) != arrival:
            continue
        if (node == data["target"] and mask == full and
                (policy != "exact" or used == budget)):
            return {"arrival": arrival}

        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], used)]
            if used < budget:
                duration = max(policy[1], edge["duration"] - edge.get("discount", 0))
                choices.append((duration, used + 1))
            for duration, next_used in choices:
                next_time = depart + duration
                if next_time > deadline:
                    continue
                dest = edge["v"]
                next_mask = mask | bit.get(dest, 0)
                next_state = (dest, next_mask, next_used)
                if next_time < best.get(next_state, float("inf")):
                    best[next_state] = next_time
                    heapq.heappush(queue, (next_time, dest, next_mask, next_used))
    return {"arrival": None}


def _build_route(rule, minimum):
    def solve(data):
        return _route((rule, minimum), data)
    return solve


def _build_component_06():
    def rounded(numerator, denominator, mode):
        if mode == "half_up":
            return (2 * numerator + denominator) // (2 * denominator)
        return numerator // denominator

    def amount(event, mode):
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = rounded(raw * (10000 - discount), 10000, mode)
        tax = rounded(net * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        return -total if event.get("kind") == "refund" else total

    def solve(data):
        cutoff = data.get("cutoff", 10**9)
        chosen = {}
        for position, event in enumerate(data["events"]):
            if event.get("sequence", 0) > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(position))
            rank = (event.get("revision", 0), position)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            key = (event.get("account", "default") + "|" +
                   event.get("currency", "USD"))
            balances[key] = balances.get(key, 0) + amount(event, data["rounding"])
        return {"balances": balances}
    return solve


def _build_component_07():
    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        initial_constraints = {
            name: (bounds[0], bounds[1])
            for name, bounds in data["roots"].items()
        }
        best_vector = None
        best_versions = None

        def acyclic(selected):
            edges = {}
            for name, version in selected.items():
                row = next(row for row in packages[name]
                           if row["version"] == version)
                active = []
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if not feature or feature in features:
                        active.append(dep["name"])
                edges[name] = active
            finished, active = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges.get(name, []):
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            return all(visit(name) for name in selected)

        def search(constraints, selected):
            nonlocal best_vector, best_versions
            unresolved = sorted(name for name in constraints if name not in selected)
            if not unresolved:
                if not acyclic(selected):
                    return
                vector = tuple(selected.get(name, -1) for name in names)
                if best_vector is None or vector < best_vector:
                    best_vector = vector
                    best_versions = dict(selected)
                return

            name = unresolved[0]
            low, high = constraints[name]
            rows = [row for row in packages.get(name, [])
                    if low <= row["version"] <= high
                    and row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            for row in rows:
                version = row["version"]
                next_selected = dict(selected)
                next_selected[name] = version
                next_constraints = dict(constraints)
                valid = True
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    dep_name = dep["name"]
                    dep_low, dep_high = dep["min"], dep["max"]
                    if dep_name in next_constraints:
                        old_low, old_high = next_constraints[dep_name]
                        dep_low = max(dep_low, old_low)
                        dep_high = min(dep_high, old_high)
                    if dep_low > dep_high:
                        valid = False
                        break
                    next_constraints[dep_name] = (dep_low, dep_high)
                    if (dep_name in next_selected and
                            not dep_low <= next_selected[dep_name] <= dep_high):
                        valid = False
                        break
                if valid:
                    search(next_constraints, next_selected)

        search(initial_constraints, {})
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _build_component_08():
    def solve(data):
        k = data["k"]
        blocked = set(data.get("blocked", []))
        jobs = [job for job in data["jobs"] if job["id"] not in blocked]
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best_value = None
        best_ids = None

        if len(jobs) < k:
            return {"error": "impossible"}
        for subset in combinations(jobs, k):
            ids = {job["id"] for job in subset}
            if not mandatory.issubset(ids):
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["end"] > ordered[i + 1]["start"]
                   for i in range(len(ordered) - 1)):
                continue
            value = sum(job["value"] for job in subset)
            ids_sorted = sorted(ids)
            if (best_value is None or value > best_value or
                    (value == best_value and ids_sorted > best_ids)):
                best_value = value
                best_ids = ids_sorted

        if best_value is None:
            return {"error": "impossible"}
        return {"selected": best_ids, "value": best_value}
    return solve


